-- Sovietski: the SUMi-224 Stormbringer gunship and the SUT-93 Firefang fighter, with its Sunburst bays and chaff dispenser (printed 176-182).
-- 2 vehicle rows, with 24 locations and 13 weapon entries.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~386-sovietski-v2.sql
--
-- Written by scripts/vessel-sql.mjs from 1 worker file(s). Every value
-- is printable ASCII, every row cites its book, and a Main Body location
-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('sumi-224-stormbringer', 'SUMi-224 Stormbringer Gunship and Transport', 'rifts', 'vehicle', 'Five: pilot, co-pilot/weapons officer, two gunners and a winch operator (usually a Light or Heavy Machine).', '16 soldiers or Light Machines, or 8 Heavy Machines, in the troop compartment; 2-4 Superheavy Machines ride slung beneath it on the cargo hook. Halve the troops when it carries two Red Squalls.', '10 mph (16 km).', '240 mph (384 km); hovers in place and takes off and lands vertically. Ceiling 18,000 feet (5,486 m). Range effectively unlimited.', 'None.', 'Height 22 feet (6.7 m), wingspan 34 feet (10.4 m), length 64 feet (19.5 m).', '23 tons fully armed; carries up to 40 tons more', 560, 1, NULL, 10000000, 'Black Market: 10-12 million credits, and extremely rare.', 'A pre-Cataclysm New Soviet successor to the old Mi-24 gunship, keeping its famous twin bubble canopies but trading the rotor for a big hover-jet in the hull plus a little tail fan jet. The widened hull holds a squad, loaded through a door on each side or a large rear hatch; the floor also opens so the tow winch can raise or lower supply pallets, cyborgs or a Red Squall straight through the cabin. A Red Squall is normally just released at 3,000-6,000 feet (914-1,828 m) so it can start flying on the way down. Its heavy nose rail gun makes it as much a flying tank and monster killer as a troop carrier: it backs up soldiers in the field, hunts demons, monsters and enemy vehicles, and can dogfight Warlord Wing Riders, dragons and Gargoyles. Because of the VTOL system, losing a wing or the tail does not bring it down, but costs -15% to piloting and -2 to dodge; depleting the Main Body shuts it down and crashes it in flight. Each crewman has a stowed rifle, sidearm, light body armor and jet pack. Nuclear, 12-year life. Standard Sovietski sensors, plus an electronic counter-measure suite that jams enemy radio within 25 miles (40 km) and traces jammed transmissions and homing beacons, and a radar detector that tells Warlord, Sovietski, NGR and outside radars apart.', 'Rifts World Book 36: Sovietski p.176-179'),
  ('sut-93-firefang', 'SUT-93 Firefang Multi-Role Jet Fighter', 'rifts', 'vehicle', 'One pilot.', 'None.', '10 mph (16 km), for taxiing only.', 'Mach 2 (1,340 mph/2,144 km) top, 330 mph (528 km) cruising, down to 100 mph (160 km) when landing or attacking ground forces. STOVL: short take-off, vertical landing. Ceiling 45,000 feet (13,716 m).', 'None.', 'Height 15 feet (4.6 m), wingspan 35 feet (10.7 m), length 51 feet 6 inches (15.7 m).', '35 tons fully armed; 30 tons without the wing hard points', 300, 1, NULL, 39000000, 'Black Market: 39 million credits, and extremely rare. The few on sale are rebuilt wrecks with 35% less M.D.C. than listed.', 'The one fighter the Sovietski flies, a cheap-to-build, rugged pre-Rifts design chosen for its range of roles rather than raw speed or agility. Warlord cities are too well guarded by anti-aircraft guns and missiles to raid, so it mostly defends: it hunts flying foes and monsters and supports troops in the field, striking massed infantry, slow vehicles and fixed positions. Short take-off and vertical landing let it use fields, tundra, ice, roads and town squares. The Sovietski has no air force; these are army pilots, trained at besieged Kaliningrad and now and then alongside the NGR, the best flyers in Russia though behind the NGR''s and the Coalition''s. Sovietski engineers added the namesake belly cannon, which ate into the missile bays. The cannon is nearly impossible to hit: only with its port open, by a Called Shot at -6, and such a hit has a 10% chance to blow it up for 5D6x10 M.D. to the Main Body, frying every system and sending a surviving jet down; High Command accepts the risk. Losing a wing crashes it unless the pilot ejects. Each lost tail fin costs 20% speed, -20% piloting and -3 dodge, doubled for two; a third crashes it. One lost jet thruster halves speed and altitude, with -30% piloting and -3 dodge; both crash it. Small targets are -4 to strike by Called Shot, -10 at Mach 1 or more. Behind the seat: first aid kit, a week of rations, a gallon (3.8 l) of water and a pistol. Nuclear, 15-year life. Standard Sovietski sensors plus a 300 mile (480 km) AESA radar tracking 64 targets with terrain following, secure links to 32 aircraft, the 25 mile (40 km) jammer and the radar detector.', 'Rifts World Book 36: Sovietski p.180-182');

INSERT OR IGNORE INTO vehicle_locations (vehicle_slug, location, mdc, mdc_note, ordinal) VALUES
  ('sumi-224-stormbringer', 'Landing Gear (3)', 25, 'Each; concealed until needed.', 1),
  ('sumi-224-stormbringer', 'Main VTOL Fan Thruster', 220, NULL, 2),
  ('sumi-224-stormbringer', 'Secondary Thrusters (3)', 100, 'Each. Small target: Called Shot only, -3 to strike.', 3),
  ('sumi-224-stormbringer', 'Side Doors (2)', 120, 'Each.', 4),
  ('sumi-224-stormbringer', 'Underside Deployment Hatch', 150, NULL, 5),
  ('sumi-224-stormbringer', 'Nose Rail Gun Turret', 100, NULL, 6),
  ('sumi-224-stormbringer', 'Weapon Wings (2)', 240, 'Each; they house the missiles. Losing one does not down the aircraft but costs -15% piloting and -2 dodge.', 7),
  ('sumi-224-stormbringer', 'Wing Laser Guns (2)', 75, 'Each; one per wing.', 8),
  ('sumi-224-stormbringer', 'Tail Wing Laser Turrets (2)', 120, 'Each; one per tail wing.', 9),
  ('sumi-224-stormbringer', 'Sensor Domes (2)', 30, 'Each; above the cockpit. Small target: Called Shot only, -3 to strike. Losing them takes long-range communications and all optical and sensor aids: the pilot loses his piloting skill and feature bonuses.', 10),
  ('sumi-224-stormbringer', 'Tail Section', 250, 'Losing it does not down the aircraft but costs -15% piloting and -2 dodge.', 11),
  ('sumi-224-stormbringer', 'Reinforced Pilot Compartment', 100, NULL, 12),
  ('sumi-224-stormbringer', 'Main Body', 560, 'Depleting it shuts the vehicle down; in flight, it crashes.', 13),
  ('sut-93-firefang', 'Main Jet Thrusters (2)', 120, 'Each. Losing one halves speed and altitude, -30% piloting, -3 dodge; losing both crashes it.', 1),
  ('sut-93-firefang', 'VTOL Thrusters (4)', 40, 'Each; underbelly. Small target: Called Shot only, -4 to strike (-10 at Mach 1 or faster).', 2),
  ('sut-93-firefang', 'Wings (2)', 140, 'Each. Losing one makes the jet unstable and it crashes unless the pilot ejects.', 3),
  ('sut-93-firefang', 'Tail Fins (4)', 55, 'Each; two top, two side. One lost: -20% speed, -20% piloting, -3 dodge; two double that; a third crashes it.', 4),
  ('sut-93-firefang', 'Firefang Cannon', 50, 'Inside the belly: hit only when its port is open, by a Called Shot at -6. A hit has a 10% chance to explode it for 5D6x10 M.D. to the Main Body.', 5),
  ('sut-93-firefang', 'Wing Lasers (2)', 20, 'Each. Small target: Called Shot only, -4 to strike (-10 at Mach 1 or faster).', 6),
  ('sut-93-firefang', 'Weapon Pods (2)', 15, 'Each; optional, on the hard points. Small target: Called Shot only, -4 to strike (-10 at Mach 1 or faster).', 7),
  ('sut-93-firefang', 'Hard Points (2)', 5, 'Each; one per wing. Small target: Called Shot only, -4 to strike (-10 at Mach 1 or faster).', 8),
  ('sut-93-firefang', 'Landing Gear (3)', 15, 'Each. Small target: Called Shot only, -4 to strike (-10 at Mach 1 or faster).', 9),
  ('sut-93-firefang', 'Reinforced Pilot Compartment', 100, NULL, 10),
  ('sut-93-firefang', 'Main Body', 300, 'Depleting it destroys the aircraft, which crashes.', 11);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('sumi-224-stormbringer', 1, 'Heavy Four-Barrel Rail Gun Turret (nose)', '1D4x10 M.D. per 20-round burst from two barrels, 2D4x10 M.D. from all four. Burst fire only.', 1, '4,000 feet (1,219 m)', 'Each burst uses one of the pilot''s melee attacks.', '8,000-round internal magazine: 200 four-barrel bursts or 400 two-barrel bursts.', NULL, 'Under the nose; 180-degree vertical arc and full 360-degree rotation, so it fires ahead, to the sides, behind, under the belly and at the ground. Anti-personnel and anti-armor, then anti-flyer and anti-missile. A dedicated gunner works it, with the pilot as emergency backup.'),
  ('sumi-224-stormbringer', 2, 'Weapon Wing Short-Range Missile Launchers (7 per wing)', 'Standard load per wing: 3 heavy high explosive and 4 plasma, each 2D6x10 M.D. to a 15 foot (4.6 m) blast radius. Any short-range missile can be loaded.', 1, '5 miles (8 km)', 'Single shots, or volleys of 2, 3, 4 or 7.', '14: seven in each weapon wing.', NULL, 'Hard points inside each weapon wing; each wing has its own dedicated gunner. Anti-tank and anti-cyborg, then assault. Missile types: Rifts Ultimate Edition p.363.'),
  ('sumi-224-stormbringer', 3, 'Weapon Wing Mini-Missile Launchers (2, one per wing)', 'Standard load: 17 armor piercing (1D4x10 M.D.), 17 plasma (1D6x10 M.D. to a 15 foot/4.6 m radius) and 2 smoke (20 foot/6.1 m radius). Any mini-missile can be loaded.', 1, 'One mile (1.6 km)', 'Single shots, or volleys of 2, 3, 4, 6 or 12.', '36: 18 in each wing launcher.', NULL, 'Inside each weapon wing, worked by that wing''s gunner. Anti-cyborg, anti-missile and anti-personnel, then assault. (The book prints two Primary Purpose lines for it.)'),
  ('sumi-224-stormbringer', 4, 'Wing-Mounted Lasers (2)', '4D6 M.D. single shot, 1D4x10 M.D. dual blast from both wings at one target', 1, '4,000 feet (1,219 m)', 'A single or a dual blast uses one melee attack.', 'Effectively unlimited.', NULL, 'At each weapon wing tip, firing ahead in a 90-degree vertical arc. Pilot controlled. Assault, then anti-armor.'),
  ('sumi-224-stormbringer', 5, 'Door Rail Guns (2)', '3D6 M.D. per short 10-round burst, 6D6 M.D. per long 20-round burst', 1, '4,000 feet (1,219 m)', 'Each burst uses one melee attack.', '1,200-round internal magazine per gun: 60 long bursts each.', NULL, 'One inside each side door, folding away for loading and swinging out as a door-gunner post when the door is open; each needs a crewman or a carried soldier to fire it. Covers troops and clears landing zones. Defense, then anti-personnel.'),
  ('sumi-224-stormbringer', 6, 'Tail Lasers (2)', '4D6 M.D. single shot, 1D4x10 M.D. dual blast from both tail weapons at one target', 1, '4,000 feet (1,219 m)', 'A single or a dual blast uses one melee attack.', 'Effectively unlimited.', NULL, 'At each tail wing tip, turning a full 360 degrees vertically so they fire ahead, up, down and behind. A gunner or another crewman works one or both. Assault, then anti-armor.'),
  ('sut-93-firefang', 1, 'Pulse Wing Lasers (2)', '2D6 M.D. single blast from one laser, 4D6 M.D. triple pulse from one, 1D4x10 M.D. fire-linked pulse from both at one target', 1, '4,000 feet (1,219 m)', 'Each shot or burst uses one of the pilot''s melee attacks.', 'Effectively unlimited.', NULL, 'One at each wing tip, for dogfights and strafing. Anti-aircraft, then defense and assault.'),
  ('sut-93-firefang', 2, 'Sunburst Internal Weapons Bays (2)', 'Per mini-missile, usually all four alike: armor piercing 1D4x10 M.D., high explosive 5D6 M.D. or plasma 1D6x10 M.D. Cumulative; 4D4x10 M.D. as a quick roll.', 1, '5 miles (8 km) for the Sunburst; each mini-missile then flies up to one mile (1.6 km) more', 'Single shots or volleys of two.', 'Six Sunburst missiles, three per bay.', '+3 to strike for each mini-missile (its own laser targeting).', 'Bays hidden outboard of each air intake, holding the pre-Cataclysm Sunburst: a short-range air-to-air missile that splits about half a mile (0.8 km) from its target into four mini-missiles, each going after one of the four nearest enemies. Set to send all four at one target, it leaves that target no dodge, though the small missiles can be shot at, at -2. Anti-aircraft and anti-Gargoyle/flyer, then anti-missile.'),
  ('sut-93-firefang', 3, 'Firefang Cannon', '6D6+10 M.D. per blast', 1, '2,000 feet (610 m)', 'Single shots only; each uses one melee attack.', 'Effectively unlimited.', NULL, 'A plasma cannon running most of the belly, firing incendiary napalm-like blasts through a port that opens to fire; deadly to aircraft and flying cyborgs. Fire-resistant Gargoyles, demons and Deevils often take half or nothing, so an ion cannon refit is being discussed. Assault, then anti-cyborg.'),
  ('sut-93-firefang', 4, 'Wing Hard Point Option A: Free-Fall Bomb Pod/Ejector Rack', 'As short-range missiles of the same type, with double the blast radius', 1, 'Dropped on ground targets; forward momentum carries a bomb about half a mile (805 m) from release', '1, 2, 3 or 4.', 'Four bombs per rack; up to one pod per wing.', NULL, 'For stationary or slow targets. Anti-installation/fortification, then anti-armor. Any pod: -5% speed, -5% piloting and -1 dodge while mounted; pods can be jettisoned when empty.'),
  ('sut-93-firefang', 5, 'Wing Hard Point Option B: Mini-Missile Pod', 'Any mini-missile; varies by type', 1, 'One mile (1.6 km)', 'Single shots, or volleys of 2, 3, 4 or 6.', 'Six per pod; 12 with a pod on each wing.', NULL, 'Rapid-fire mini-missiles for ground targets and close air targets. Anti-personnel and assault, then anti-missile and anti-flyer. Pod penalties as Option A.'),
  ('sut-93-firefang', 6, 'Wing Hard Point Option C: Short-Range Missile Pod', 'Any short-range missile; varies by type', 1, 'Varies with missile type', 'Single shots, or volleys of 2, 3, 4 or 6; the last two only with a pod on both wings.', 'Three per pod; 6 with a pod on each wing.', NULL, 'Larger missiles. Anti-aircraft, then anti-fortification/installation. Pod penalties as Option A.'),
  ('sut-93-firefang', 7, 'Anti-Missile Chaff Dispenser', 'None. Roll percentile per pursuing missile or volley: 01-50 it detonates in the cloud; 51-75 it loses the target and veers off (it may lock onto a nearby aircraft); 76-00 no effect.', 0, NULL, NULL, 'Four.', NULL, 'In the tail. The cloud also blinds Gargoyles and other creatures flying through it for 1D4 melee rounds (15-60 seconds), with no lasting harm. Anti-missile.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 machines are in' AS assertion, count(*) AS got, 2 AS want
  FROM vehicles WHERE slug IN ('sumi-224-stormbringer', 'sut-93-firefang');
SELECT 'their 24 locations are in' AS assertion, count(*) AS got, 24 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('sumi-224-stormbringer', 'sut-93-firefang');
SELECT 'their 13 weapon entries are in' AS assertion, count(*) AS got, 13 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('sumi-224-stormbringer', 'sut-93-firefang');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('sumi-224-stormbringer', 'sut-93-firefang') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

